#!/usr/bin/env node
// Admin panel server generated by DB Admin Generator (ZCode). No dependencies: Node >= 22.13 (node:sqlite, node:http).
//   node server.mjs                          start (http://127.0.0.1:8787 by default; PORT / HOST / ADMIN_DB env to change)
//   node server.mjs user add <name> <role>   add a user (role: admin | editor | viewer); password from ADMIN_PASSWORD or generated
//   node server.mjs user passwd <name>       set a new password
//   node server.mjs user list | user remove <name>
import { appendFileSync, chmodSync, existsSync, readFileSync, writeFileSync } from "node:fs";
import { createServer } from "node:http";
import { createHmac, randomBytes, scryptSync, timingSafeEqual } from "node:crypto";
import { dirname, join, resolve } from "node:path";
import { fileURLToPath } from "node:url";
import { DatabaseSync } from "node:sqlite";
import { editable, introspect, labelColumn, quoteIdent as qi, required, validateRow } from "./schema.mjs";

const HERE = dirname(fileURLToPath(import.meta.url));
const CFG = JSON.parse(readFileSync(join(HERE, "admin.config.json"), "utf8"));
const DB_PATH = resolve(HERE, process.env.ADMIN_DB || CFG.db);
const USERS = resolve(HERE, process.env.ADMIN_USERS || "users.json");
const SECRET_FILE = resolve(HERE, process.env.ADMIN_SECRET_FILE || ".session-secret");
const AUDIT = resolve(HERE, process.env.ADMIN_AUDIT || "audit.log");
const ROLES = CFG.roles || { admin: ["read", "create", "update", "delete"], editor: ["read", "create", "update"], viewer: ["read"] };
const ZH = CFG.lang === "zh";
const L = ZH ? { login: "用户名或密码不对", locked: "尝试次数过多，请 10 分钟后再试", auth: "请先登录", forbid: "你的角色没有这个权限", nf: "找不到", bad: "请求无效", dup: "已存在相同的值", inuse: "还有其他记录引用它，不能删除", fkbad: "引用的记录不存在", check: "不符合数据库的约束", fix: "请修正标出的字段", nothing: "没有要保存的修改" }
  : { login: "Wrong user name or password", locked: "Too many attempts; try again in 10 minutes", auth: "Please sign in", forbid: "Your role is not allowed to do this", nf: "Not found", bad: "Bad request", dup: "This value already exists", inuse: "Other records still refer to this one; it can't be deleted", fkbad: "The referenced record does not exist", check: "Violates a database constraint", fix: "Please fix the marked fields", nothing: "Nothing to save" };

// ---------- users ----------
const readUsers = () => (existsSync(USERS) ? JSON.parse(readFileSync(USERS, "utf8")) : {});
const writeUsers = (u) => { writeFileSync(USERS, JSON.stringify(u, null, 1) + "\n", { mode: 0o600 }); try { chmodSync(USERS, 0o600); } catch {} };
const hash = (pw, salt = randomBytes(16).toString("hex")) => `scrypt$${salt}$${scryptSync(pw, salt, 32).toString("hex")}`;
const verify = (pw, stored) => { const [, salt, h] = String(stored).split("$"); if (!salt || !h) return false; const a = Buffer.from(scryptSync(pw, salt, 32).toString("hex")), b = Buffer.from(h); return a.length === b.length && timingSafeEqual(a, b); };
const genPw = () => randomBytes(12).toString("base64url");
function userCli(args) {
  const [cmd, name, role] = args, users = readUsers();
  if (cmd === "list") { for (const [n, u] of Object.entries(users)) console.log(`${n}\t${u.role}`); return; }
  if (cmd === "remove") { if (!users[name]) throw new Error(`no user ${name}`); delete users[name]; writeUsers(users); console.log(`removed ${name}`); return; }
  if (cmd === "add" || cmd === "passwd") {
    if (!name || !/^[\w.@-]{1,64}$/.test(name)) throw new Error("user name: letters, digits, . _ - @");
    if (cmd === "add" && !ROLES[role]) throw new Error(`role must be one of: ${Object.keys(ROLES).join(", ")}`);
    if (cmd === "passwd" && !users[name]) throw new Error(`no user ${name}`);
    const given = process.env.ADMIN_PASSWORD, pw = given || genPw();
    if (given && given.length < 8) throw new Error("ADMIN_PASSWORD must be at least 8 characters");
    users[name] = { role: cmd === "add" ? role : users[name].role, hash: hash(pw), created: users[name]?.created ?? new Date().toISOString() };
    writeUsers(users);
    console.log(`${cmd === "add" ? "added" : "updated"} ${name} (${users[name].role})${given ? "" : `; password: ${pw}`}`);
    return;
  }
  throw new Error("usage: node server.mjs user add <name> <role> | passwd <name> | list | remove <name>");
}

// ---------- sessions ----------
function secret() {
  if (!existsSync(SECRET_FILE)) writeFileSync(SECRET_FILE, randomBytes(32).toString("hex"), { mode: 0o600 });
  return readFileSync(SECRET_FILE, "utf8").trim();
}
const sign = (payload, key) => { const b = Buffer.from(JSON.stringify(payload)).toString("base64url"); return `${b}.${createHmac("sha256", key).update(b).digest("base64url")}`; };
function unsign(token, key) {
  const [b, s] = String(token || "").split(".");
  if (!b || !s) return null;
  const want = createHmac("sha256", key).update(b).digest("base64url");
  if (want.length !== s.length || !timingSafeEqual(Buffer.from(want), Buffer.from(s))) return null;
  try { const p = JSON.parse(Buffer.from(b, "base64url").toString()); return p.e > Date.now() ? p : null; } catch { return null; }
}
const cookies = (req) => Object.fromEntries(String(req.headers.cookie || "").split(/;\s*/).filter(Boolean).map((c) => { const i = c.indexOf("="); return [c.slice(0, i), decodeURIComponent(c.slice(i + 1))]; }));

// ---------- database ----------
function openDb() {
  if (!existsSync(DB_PATH)) throw new Error(`Database not found: ${DB_PATH}`);
  const db = new DatabaseSync(DB_PATH);
  db.exec("PRAGMA foreign_keys = ON; PRAGMA busy_timeout = 3000;");
  return db;
}

class HttpError extends Error { constructor(status, message, fields) { super(message); this.status = status; this.fields = fields; } }

function buildModel(db) {
  const schema = introspect(db);
  const out = new Map();
  for (const tc of CFG.tables || []) {
    const t = schema.find((x) => x.name === tc.name);
    if (!t) { console.warn(`! table ${tc.name} from admin.config.json is not in the database; skipped`); continue; }
    const cols = new Set(t.columns.map((c) => c.name));
    const ops = (tc.ops || ["read"]).filter((o) => t.type === "table" || o === "read");
    const keyed = t.type === "table";
    out.set(t.name, {
      t, ops, label: tc.label || t.name, labelColumn: cols.has(tc.labelColumn) ? tc.labelColumn : labelColumn(t),
      list: (tc.list || t.columns.slice(0, 7).map((c) => c.name)).filter((c) => cols.has(c)),
      search: (tc.search || t.columns.filter((c) => ["text", "email", "tel", "longtext", "url", "select"].includes(c.kind)).map((c) => c.name)).filter((c) => cols.has(c)),
      hidden: new Set((tc.hidden || []).filter((c) => cols.has(c))),
      keyCols: !keyed ? [] : t.rowid ? ["rowid"] : t.pk,
    });
  }
  return { schema, tables: out };
}

const escLike = (s) => s.replace(/[\\%_]/g, (c) => `\\${c}`);
function keyWhere(m, key) {
  let vals;
  try { vals = JSON.parse(key); } catch { throw new HttpError(400, L.bad); }
  if (!Array.isArray(vals) || vals.length !== m.keyCols.length || !m.keyCols.length) throw new HttpError(400, L.bad);
  return { sql: m.keyCols.map((c) => `${c === "rowid" ? "rowid" : qi(c)} = ?`).join(" AND "), params: vals };
}
const keySelect = (m) => (m.keyCols.length ? m.keyCols.map((c, i) => `${c === "rowid" ? "rowid" : qi(c)} AS "__k${i}"`).join(", ") + ", " : "");
function shape(m, row) {
  const o = { _key: m.keyCols.length ? JSON.stringify(m.keyCols.map((_, i) => row[`__k${i}`])) : null };
  for (const c of m.t.columns) if (!m.hidden.has(c.name)) o[c.name] = row[c.name];
  return o;
}
function fkLabels(db, model, m, rows) {
  const labels = {};
  for (const c of m.t.columns) {
    if (!c.fk || !rows.length) continue;
    const target = model.schema.find((x) => x.name === c.fk.table);
    if (!target) continue;
    const lc = model.tables.get(target.name)?.labelColumn ?? labelColumn(target);
    const vals = [...new Set(rows.map((r) => r[c.name]).filter((v) => v !== null && v !== undefined))];
    if (!vals.length) continue;
    const res = db.prepare(`SELECT ${qi(c.fk.column)} AS v, ${qi(lc)} AS l FROM ${qi(target.name)} WHERE ${qi(c.fk.column)} IN (${vals.map(() => "?").join(",")})`).all(...vals);
    labels[c.name] = Object.fromEntries(res.map((r) => [String(r.v), r.l]));
  }
  return labels;
}
function mapSqlError(e, t) {
  const msg = String(e?.message || e);
  let m = /UNIQUE constraint failed: ([^\n]+)/.exec(msg);
  if (m) { const fields = {}; for (const part of m[1].split(",")) fields[part.trim().split(".").pop()] = L.dup; return new HttpError(409, L.dup, fields); }
  m = /NOT NULL constraint failed: \S+\.(\S+)/.exec(msg);
  if (m) return new HttpError(400, L.fix, { [m[1]]: ZH ? "必填" : "Required" });
  if (/FOREIGN KEY constraint failed/.test(msg)) return new HttpError(409, t === "delete" ? L.inuse : L.fkbad);
  if (/CHECK constraint failed/.test(msg)) return new HttpError(400, `${L.check}: ${msg.replace(/^.*CHECK constraint failed: /, "")}`);
  return new HttpError(500, msg);
}
const audit = (user, action, table, key) => { try { appendFileSync(AUDIT, `${new Date().toISOString()}\t${user}\t${action}\t${table}\t${key ?? ""}\n`); } catch {} };

// ---------- http ----------
const STATIC = { "/": ["index.html", "text/html; charset=utf-8"], "/app.js": ["app.js", "text/javascript; charset=utf-8"], "/style.css": ["style.css", "text/css; charset=utf-8"] };
function send(res, status, body, type = "application/json; charset=utf-8", extra = {}) {
  res.writeHead(status, { "Content-Type": type, "X-Content-Type-Options": "nosniff", "X-Frame-Options": "DENY", "Referrer-Policy": "no-referrer", "Cache-Control": "no-store",
    "Content-Security-Policy": "default-src 'self'; img-src 'self' data:; style-src 'self'; script-src 'self'; frame-ancestors 'none'; base-uri 'none'; form-action 'self'", ...extra });
  res.end(typeof body === "string" || Buffer.isBuffer(body) ? body : JSON.stringify(body));
}
const readBody = (req) => new Promise((ok, fail) => {
  let n = 0; const chunks = [];
  req.on("data", (c) => { n += c.length; if (n > 1_000_000) { fail(new HttpError(413, "Too large")); req.destroy(); } else chunks.push(c); });
  req.on("end", () => { try { ok(chunks.length ? JSON.parse(Buffer.concat(chunks).toString("utf8")) : {}); } catch { fail(new HttpError(400, L.bad)); } });
  req.on("error", fail);
});

export function start({ port = Number(process.env.PORT ?? CFG.port ?? 8787), host = process.env.HOST || "127.0.0.1" } = {}) {
  const db = openDb();
  const model = buildModel(db);
  const key = secret();
  const fails = new Map();
  const ttl = (CFG.sessionHours ?? 12) * 3600_000;
  const server = createServer(async (req, res) => {
    const url = new URL(req.url, "http://x");
    const path = url.pathname;
    try {
      if (req.method === "GET" && STATIC[path]) { const [f, type] = STATIC[path]; return send(res, 200, readFileSync(join(HERE, "public", f)), type); }
      if (path === "/favicon.ico") { res.writeHead(204); return res.end(); }
      if (!path.startsWith("/api/")) throw new HttpError(404, L.nf);
      if (req.method !== "GET" && req.headers["x-admin"] !== "1") throw new HttpError(403, "Missing X-Admin header");
      if (path === "/api/login" && req.method === "POST") {
        const ip = req.socket.remoteAddress || "?", f = fails.get(ip);
        if (f && f.n >= 5 && Date.now() - f.t < 600_000) throw new HttpError(429, L.locked);
        const { user, password } = await readBody(req);
        const u = readUsers()[String(user || "")];
        if (!u || !verify(String(password || ""), u.hash)) { fails.set(ip, { n: (f && Date.now() - f.t < 600_000 ? f.n : 0) + 1, t: Date.now() }); throw new HttpError(401, L.login); }
        fails.delete(ip);
        const secure = req.headers["x-forwarded-proto"] === "https" ? "; Secure" : "";
        return send(res, 200, { ok: true, user, role: u.role }, undefined, { "Set-Cookie": `adm=${encodeURIComponent(sign({ u: user, e: Date.now() + ttl }, key))}; HttpOnly; SameSite=Strict; Path=/; Max-Age=${ttl / 1000 | 0}${secure}` });
      }
      if (path === "/api/logout" && req.method === "POST") return send(res, 200, { ok: true }, undefined, { "Set-Cookie": "adm=; HttpOnly; SameSite=Strict; Path=/; Max-Age=0" });
      const sess = unsign(cookies(req).adm, key), u = sess && readUsers()[sess.u];
      if (!u || !ROLES[u.role]) throw new HttpError(401, L.auth);
      const user = sess.u, can = (m, op) => m.ops.includes(op) && ROLES[u.role].includes(op);
      if (path === "/api/meta") {
        return send(res, 200, { title: CFG.title, lang: CFG.lang, user, role: u.role, pageSize: CFG.pageSize ?? 25, tables: [...model.tables.values()].filter((m) => can(m, "read")).map((m) => ({
          name: m.t.name, label: m.label, view: m.t.type === "view", rows: m.t.rows, keyed: m.keyCols.length > 0, labelColumn: m.labelColumn, list: m.list.filter((c) => !m.hidden.has(c)), search: m.search,
          ops: ["read", "create", "update", "delete"].filter((o) => can(m, o)),
          columns: m.t.columns.filter((c) => !m.hidden.has(c.name)).map((c) => ({ name: c.name, kind: c.kind, type: c.type, required: required(c), editable: editable(c), auto: c.auto, pk: c.pk > 0, options: c.options, maxLength: c.maxLength, fk: c.fk ? { table: c.fk.table, column: c.fk.column } : undefined, default: c.default })),
        })) });
      }
      const mt = /^\/api\/t\/([^/]+)(?:\/(r|options)\/([^/]+))?$/.exec(path);
      if (!mt) throw new HttpError(404, L.nf);
      const m = model.tables.get(decodeURIComponent(mt[1]));
      if (!m || !can(m, "read")) throw new HttpError(404, L.nf);
      const T = qi(m.t.name);
      if (mt[2] === "options") {
        const c = m.t.columns.find((x) => x.name === decodeURIComponent(mt[3]));
        if (!c?.fk) throw new HttpError(404, L.nf);
        const target = model.schema.find((x) => x.name === c.fk.table);
        if (!target) throw new HttpError(404, L.nf);
        const lc = model.tables.get(target.name)?.labelColumn ?? labelColumn(target);
        return send(res, 200, { options: db.prepare(`SELECT ${qi(c.fk.column)} AS value, ${qi(lc)} AS label FROM ${qi(target.name)} ORDER BY 2 LIMIT 2000`).all() });
      }
      if (mt[2] === "r") {
        const w = keyWhere(m, decodeURIComponent(mt[3]));
        if (req.method === "GET") {
          const row = db.prepare(`SELECT ${keySelect(m)}* FROM ${T} WHERE ${w.sql}`).get(...w.params);
          if (!row) throw new HttpError(404, L.nf);
          return send(res, 200, { row: shape(m, row), labels: fkLabels(db, model, m, [row]) });
        }
        if (req.method === "PUT") {
          if (!can(m, "update")) throw new HttpError(403, L.forbid);
          const body = await readBody(req);
          for (const h of m.hidden) delete body[h];
          const { values, errors } = validateRow(m.t, body, "update", CFG.lang);
          if (Object.keys(errors).length) throw new HttpError(400, L.fix, errors);
          const cols = Object.keys(values);
          if (!cols.length) throw new HttpError(400, L.nothing);
          let r;
          try { r = db.prepare(`UPDATE ${T} SET ${cols.map((c) => `${qi(c)} = ?`).join(", ")} WHERE ${w.sql}`).run(...cols.map((c) => values[c]), ...w.params); } catch (e) { throw mapSqlError(e, "update"); }
          if (!r.changes) throw new HttpError(404, L.nf);
          audit(user, "update", m.t.name, mt[3]);
          const nk = m.keyCols.map((c, i) => (c in values ? values[c] : w.params[i]));
          const row = db.prepare(`SELECT ${keySelect(m)}* FROM ${T} WHERE ${keyWhere(m, JSON.stringify(nk)).sql}`).get(...nk);
          return send(res, 200, { row: row ? shape(m, row) : null });
        }
        if (req.method === "DELETE") {
          if (!can(m, "delete")) throw new HttpError(403, L.forbid);
          let r;
          try { r = db.prepare(`DELETE FROM ${T} WHERE ${w.sql}`).run(...w.params); } catch (e) { throw mapSqlError(e, "delete"); }
          if (!r.changes) throw new HttpError(404, L.nf);
          audit(user, "delete", m.t.name, mt[3]);
          return send(res, 200, { ok: true });
        }
        throw new HttpError(405, L.bad);
      }
      if (req.method === "POST") {
        if (!can(m, "create")) throw new HttpError(403, L.forbid);
        const body = await readBody(req);
        for (const h of m.hidden) delete body[h];
        const { values, errors } = validateRow(m.t, body, "create", CFG.lang);
        if (Object.keys(errors).length) throw new HttpError(400, L.fix, errors);
        const cols = Object.keys(values);
        let r;
        try { r = db.prepare(cols.length ? `INSERT INTO ${T} (${cols.map(qi).join(", ")}) VALUES (${cols.map(() => "?").join(", ")})` : `INSERT INTO ${T} DEFAULT VALUES`).run(...cols.map((c) => values[c])); } catch (e) { throw mapSqlError(e, "create"); }
        const row = /WITHOUT\s+ROWID/i.test(m.t.sql) ? db.prepare(`SELECT ${keySelect(m)}* FROM ${T} WHERE ${m.t.pk.map((c) => `${qi(c)} = ?`).join(" AND ")}`).get(...m.t.pk.map((c) => values[c])) : db.prepare(`SELECT ${keySelect(m)}* FROM ${T} WHERE rowid = ?`).get(r.lastInsertRowid);
        const out = row ? shape(m, row) : null;
        audit(user, "create", m.t.name, out?._key);
        return send(res, 201, { row: out });
      }
      if (req.method !== "GET") throw new HttpError(405, L.bad);
      // list
      const where = [], params = [];
      const q = (url.searchParams.get("q") || "").trim();
      if (q && m.search.length) { where.push(`(${m.search.map((c) => `CAST(${qi(c)} AS TEXT) LIKE ? ESCAPE '\\'`).join(" OR ")})`); for (const _ of m.search) params.push(`%${escLike(q)}%`); }
      for (const [k, v] of url.searchParams) {
        if (!k.startsWith("f.")) continue;
        const c = m.t.columns.find((x) => x.name === k.slice(2));
        if (!c || m.hidden.has(c.name)) throw new HttpError(400, L.bad);
        if (v === "\u2205") where.push(`${qi(c.name)} IS NULL`); else { where.push(`${qi(c.name)} = ?`); params.push(v); }
      }
      const sortCol = m.t.columns.find((x) => x.name === url.searchParams.get("sort") && !m.hidden.has(x.name));
      const dir = url.searchParams.get("dir") === "desc" ? "DESC" : "ASC";
      const order = sortCol ? `${qi(sortCol.name)} ${dir}` : m.keyCols.length ? m.keyCols.map((c) => (c === "rowid" ? "rowid" : qi(c))).join(", ") + " DESC" : "1";
      const size = Math.min(200, Math.max(1, Number(url.searchParams.get("size")) || (CFG.pageSize ?? 25)));
      const page = Math.max(0, Number(url.searchParams.get("page")) || 0);
      const W = where.length ? ` WHERE ${where.join(" AND ")}` : "";
      const total = db.prepare(`SELECT COUNT(*) AS n FROM ${T}${W}`).get(...params).n;
      const rows = db.prepare(`SELECT ${keySelect(m)}* FROM ${T}${W} ORDER BY ${order} LIMIT ? OFFSET ?`).all(...params, size, page * size);
      return send(res, 200, { total, page, size, rows: rows.map((r) => shape(m, r)), labels: fkLabels(db, model, m, rows) });
    } catch (e) {
      const status = e instanceof HttpError ? e.status : 500;
      if (status === 500) console.error(e);
      return send(res, status, { error: e.message, fields: e.fields });
    }
  });
  return new Promise((ok) => server.listen(port, host, () => {
    const a = server.address();
    console.log(`${CFG.title}: admin running at http://${a.address === "::1" ? "localhost" : a.address}:${a.port} (database ${DB_PATH})`);
    ok({ server, port: a.port, close: () => new Promise((d) => { server.close(() => { db.close(); d(); }); server.closeAllConnections?.(); }) });
  }));
}

if (process.argv[1] && resolve(process.argv[1]) === fileURLToPath(import.meta.url)) {
  const [cmd, ...rest] = process.argv.slice(2);
  try {
    if (cmd === "user") userCli(rest);
    else {
      if (!Object.keys(readUsers()).length) { const pw = process.env.ADMIN_PASSWORD || genPw(); writeUsers({ admin: { role: "admin", hash: hash(pw), created: new Date().toISOString() } }); console.log(`First start: created user "admin"${process.env.ADMIN_PASSWORD ? "" : ` with password ${pw}`} — change it with: node server.mjs user passwd admin`); }
      await start();
    }
  } catch (e) { console.error(String(e?.message || e)); process.exit(1); }
}
